def options_for_topics():
    result = {}
    for line in ROWS.strip().splitlines():
        if not line.strip():
            continue
        topic_id, *items = line.split('|')
        if topic_id in result:
            raise ValueError(f'Duplicate topic: {topic_id}')
        result[topic_id] = []
        for item in items:
            slug, title = item.split('~', 1)
            result[topic_id].append({'id': f'{topic_id}.help.{slug}', 'title': title})
    return result

